<pre><code>$conn = new PDO("mysql:host=your_host;dbname=your_db",$user,$pass);

$query = "SELECT * FROM asset_records WHERE a_category LIKE '%Desktop%' GROUP BY a_make";
$result = $connection-&gt;prepare($query);
$result-&gt;execute();


 while($row = $result-&gt;fetch()) {
     // DATA HERE
    }
</code></pre>
